import 'package:flutter/material.dart';

class p2 extends StatelessWidget {
  List<Map> items = [
    {
      "url":
          "data:image/jpeg;base64,",
      "name": "Shoes",
      "description": "Comfortable running shoes",
    },
    {
      "url":
          "data:image/jpeg;base64,",
      "name": "Watch",
      "description": "Luxury Wrist Watch",
    },
    {
      "url":
          "data:image/jpeg;base64,",
      "name": "Bag",
      "description": "Stylish School Bag",
    },
    {
      "url":
          "data:image/jpeg;base64,",
      "name": "T-Shirt",
      "description": "Cotton T-Shirt",
    },
    {
      "url":
          "data:image/jpeg;base64,",
      "name": "Headphones",
      "description": "Noice Cancellation Headphones",
    },
  ];

  p2({Key? key}) : super(key: key);

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text("Lab-12 Program-2"),
        backgroundColor: Colors.blue,
        centerTitle: true,
      ),
      body: Column(
        children: [
          Expanded(
            child: ListView.builder(
              itemCount: items.length,
              itemBuilder: (context, index) {
                var item = items[index];
                return Padding(
                  padding: const EdgeInsets.all(8.0),
                  child: Card(
                    child: ListTile(
                      leading: CircleAvatar(child: Image.network(item['url'])),
                      title: Text(item['name']),
                      subtitle: Text(item['description']),
                      trailing: ElevatedButton(
                        onPressed: () {},
                        child: Text("Details"),
                      ),
                    ),
                  ),
                );
              },
            ),
          ),
          Padding(
            padding: const EdgeInsets.all(15.0),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: [
                ElevatedButton(onPressed: () {}, child: Text("Add to cart")),
                ElevatedButton(onPressed: () {}, child: Text("Wishlist")),
              ],
            ),
          ),
        ],
      ),
    );
  }
}
